#include <bits/stdc++.h>using namespace std;#define int long longint T,n; void O_o(){	cin >> n;	vector<pair<int,pair<bool,bool>>> a(n + 1);	for(int i=1;i<=n;i++){		cin >> a[i].first;		a[i].second.first = i & 1;		a[i].second.second = (i - 1) & 1;	}	sort(a.begin() + 1,a.begin() + 1 + n);	for(int i=2;i<=n;i++){		if(a[i].second.first == a[i - 1].second.first || a[i].second.second == a[i - 1].second.second){			cout << "No" << '\n';			return ;		}	}	cout << "Yes" << '\n';} signed main(){	ios::sync_with_stdio(false);	cin.tie(nullptr);cout.tie(nullptr);	cin >> T;	while(T--)O_o();	return 0;}